DROP POLICY "Authenticated users can view Telegram contacts" ON public.telegram_contacts;
CREATE POLICY "Active staff can view Telegram contacts" ON public.telegram_contacts FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin') OR private.has_role(auth.uid(), 'content_creator'));
DROP POLICY "Authenticated users can view Telegram messages" ON public.telegram_messages;
CREATE POLICY "Active staff can view Telegram messages" ON public.telegram_messages FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin') OR private.has_role(auth.uid(), 'content_creator'));
DROP POLICY "Authenticated users can view WhatsApp history" ON public.whatsapp_messages;
CREATE POLICY "Active staff can view WhatsApp history" ON public.whatsapp_messages FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin') OR private.has_role(auth.uid(), 'content_creator'));
DROP POLICY "Staff can create WhatsApp history" ON public.whatsapp_messages;
DROP POLICY "Staff can update WhatsApp history" ON public.whatsapp_messages;
REVOKE INSERT, UPDATE, DELETE ON public.whatsapp_messages FROM anon, authenticated;
GRANT SELECT ON public.whatsapp_messages TO authenticated;
GRANT ALL ON public.whatsapp_messages TO service_role;
DROP POLICY "Admins can create Telegram messages" ON public.telegram_messages;
REVOKE INSERT, UPDATE, DELETE ON public.telegram_messages FROM anon, authenticated;
GRANT SELECT ON public.telegram_messages TO authenticated;
GRANT ALL ON public.telegram_messages TO service_role;
DROP POLICY "Users can view all profiles" ON public.profiles;
CREATE POLICY "Users can view own profile or admins" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR private.has_role(auth.uid(), 'admin'));
REVOKE ALL ON public.profiles FROM anon;
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
DROP POLICY "Users can view all roles" ON public.user_roles;
CREATE POLICY "Users can view own role or admins" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR private.has_role(auth.uid(), 'admin'));
REVOKE ALL ON public.user_roles FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
DROP POLICY "Authenticated users can view course quizzes" ON public.course_quiz_questions;
CREATE POLICY "Active staff can view course quiz answer keys" ON public.course_quiz_questions FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin') OR private.has_role(auth.uid(), 'content_creator'));
REVOKE ALL ON public.course_quiz_questions FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.course_quiz_questions TO authenticated;
GRANT ALL ON public.course_quiz_questions TO service_role;
DROP POLICY "Authenticated users can view embeddings" ON public.resource_embeddings;
CREATE POLICY "Accessible course embeddings" ON public.resource_embeddings FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.course_resources r JOIN public.course_modules m ON m.id = r.module_id JOIN public.courses c ON c.id = m.course_id WHERE r.id = resource_embeddings.resource_id AND (c.is_published OR c.created_by = auth.uid() OR private.has_role(auth.uid(), 'admin'))));
COMMENT ON TABLE public.whatsapp_messages IS 'Provider IDs and delivery states are written only by verified callback intake and authenticated server sends; active staff have read-only Data API access.';
COMMENT ON TABLE public.telegram_messages IS 'Provider message IDs are written only by trusted server code; active staff have read-only Data API access.';